import { FixedSizeList as List } from 'react-window';

function VirtualTable({ rows }) {
  const Row = ({ index, style }) => (
    <div style={style}>
      {rows[index].name} — {rows[index].value}
    </div>
  );

  return (
    <List
      height={400}
      itemCount={rows.length}
      itemSize={35}
      width="100%"
    >
      {Row}
    </List>
  );
}
